using System;
using System.Text.Json.Serialization;
using AmazonSwf.Core.Enum;

namespace AmazonSwf.Models.Enums;

/// <summary>
/// The cause of the failure. This information is generated by the system and can be useful for diagnostic purposes. If cause is set to OPERATION_NOT_PERMITTED, the decision failed because it lacked sufficient permissions. For details and example IAM policies, see Using IAM to Manage Access to Amazon SWF Workflows in the Amazon SWF Developer Guide.
/// </summary>
[JsonConverter(typeof(StringEnumConverter<Cause8>))]
public sealed record Cause8 : OpenStringEnum<Cause8>
{
    private Cause8(string value) : base(value)
    {
    }

    public static readonly Cause8 UnknownExternalWorkflowExecution = new("UNKNOWN_EXTERNAL_WORKFLOW_EXECUTION");

    public static readonly Cause8 RequestCancelExternalWorkflowExecutionRateExceeded = new(
        "REQUEST_CANCEL_EXTERNAL_WORKFLOW_EXECUTION_RATE_EXCEEDED");

    public static readonly Cause8 OperationNotPermitted = new("OPERATION_NOT_PERMITTED");

    public TResult Match<TResult>(Func<TResult> onUnknownExternalWorkflowExecution,
        Func<TResult> onRequestCancelExternalWorkflowExecutionRateExceeded,
        Func<TResult> onOperationNotPermitted,
        Func<string, TResult> otherwise) =>
        this switch
        {
            _ when this == UnknownExternalWorkflowExecution => onUnknownExternalWorkflowExecution(),
            _ when this ==
                RequestCancelExternalWorkflowExecutionRateExceeded => onRequestCancelExternalWorkflowExecutionRateExceeded(),
            _ when this == OperationNotPermitted => onOperationNotPermitted(),
            _ => otherwise(Value)
        };

    public void Match(Action onUnknownExternalWorkflowExecution,
        Action onRequestCancelExternalWorkflowExecutionRateExceeded,
        Action onOperationNotPermitted,
        Action<string> otherwise)
    {
        if (this == UnknownExternalWorkflowExecution) onUnknownExternalWorkflowExecution();
        else if (this ==
            RequestCancelExternalWorkflowExecutionRateExceeded) onRequestCancelExternalWorkflowExecutionRateExceeded();
        else if (this == OperationNotPermitted) onOperationNotPermitted();
        else otherwise(Value);
    }
}
